sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;

	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});


};

sp_widget.css:
.servicos-widget {
  font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 400; 
  display: flex;
  align-items: center;
  justify-content: center;
  max-width: 80%;
  margin: 0 auto;
  margin-left: 100px;
  position: static;
  margin-top: 25px;
}

.blue-bar {
  width: 5px;
  height: 24px;
  background-color: #ffa500;
  margin-right: 10px;
}

.servicos-text {
  font-size: 24px;
  color: #2F2F2F;
  padding: 10px;
}

.servicos-line {
  flex-grow: 1;
  height: 1px;
  background-color: transparent;
}

.lowercase-text {
  text-transform: lowercase;
}

.uppercase-text {
  text-transform: uppercase;
}


/* Media query para centralizar em telas menores */
@media (max-width: 900px) {
  .servicos-widget {
        max-width: 45%;
  }
}
